'use strict';
document.documentElement.classList.add('js');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let selectedStage=0, allStages=false;
function renderStages(){ $$('[data-stage]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===selectedStage))); $$('.stage').forEach((p,i)=>p.hidden=!allStages&&i!==selectedStage); $('#show-all').setAttribute('aria-pressed',String(allStages)); $('#show-all').textContent=allStages?'Show selected stage only':'Show all stage details'; }
$$('[data-stage]').forEach(b=>b.addEventListener('click',()=>{selectedStage=Number(b.dataset.stage);allStages=false;renderStages()}));
$('#show-all').addEventListener('click',()=>{allStages=!allStages;renderStages()});renderStages();
const unknown='Not publicly disclosed';
const models={
llama:{title:'Llama 3.1 405B',developer:'META / JULY 2024',summary:'A comparatively transparent resource case: official model-level reporting makes scope checks possible.',facts:[['Parameters','405 billion','Officially reported [1]'],['Pretraining data','≈ 15 trillion tokens','Officially reported [1]'],['Hardware','H100 80GB; up to 16K GPUs','Officially reported [1, 10]'],['Training device time','30.84M GPU-hours','Officially reported [1]'],['Location-based emissions','8,930 t CO₂e','Officially reported [1]'],['Compute rental estimate','≈ $170 million','Independently estimated [5]']],extra:'GPU-hours and emissions refer to 405B, not the whole family. Meta reports 0 market-based t CO₂e under renewable-energy matching; this does not imply zero electricity consumption. Measured energy in kWh and full elapsed duration are not separately reported in the cited model card. A constant-fleet calculation gives ≈ 78.4 equivalent days, not an observed duration (see research notes).',sources:[1,5,10]},
gpt:{title:'GPT-4',developer:'OPENAI / MARCH 2023',summary:'The technical report documents next-token pretraining and RLHF, while deliberately withholding many resource details.',facts:[['Parameters',unknown,'Not publicly disclosed [2]'],['Pretraining tokens',unknown,'Not publicly disclosed [2]'],['Hardware type / quantity',unknown,'Not publicly disclosed [2]'],['Accelerator-hours / duration',unknown,'Not publicly disclosed [2]'],['Energy / emissions',unknown,'Not publicly disclosed [2]'],['Compute rental estimate','≈ $79 million','Independently estimated [5]']],extra:'The dollar value is an external compute-cost estimate, not an OpenAI invoice or an official total development budget. Avoid substituting rumored model sizes or fleet counts for the report’s disclosure limits.',sources:[2,5]},
gemini:{title:'Gemini 1.0 Ultra',developer:'GOOGLE DEEPMIND / 2024 RELEASE',summary:'A multimodal model introduced in 2023 and released in 2024. Its report emphasizes distributed training across data centers.',facts:[['Parameters',unknown,'Not publicly disclosed [3]'],['Pretraining tokens',unknown,'Not publicly disclosed [3]'],['Hardware','TPUv4; exact count undisclosed','Officially reported type [3]'],['Accelerator-hours / duration',unknown,'Not publicly disclosed [3]'],['Energy / emissions',unknown,'Not publicly disclosed [3]'],['Compute rental estimate','≈ $192 million','Independently estimated [5]']],extra:'The report discusses TPUv4 and TPUv5e across the Gemini family, but identifies TPUv4 for Ultra. A SuperPod’s chip count does not establish the total Ultra fleet. The cost estimate uses the same Index methodology as the other bars.',sources:[3,5]},
claude:{title:'Claude 3 Opus',developer:'ANTHROPIC / MARCH 2024',summary:'The Claude 3 family report describes broad pretraining, human feedback, and Constitutional AI. It supports a training-method case study, not a numeric cost reconstruction.',facts:[['Parameters',unknown,'Not publicly disclosed [4]'],['Pretraining tokens',unknown,'Not publicly disclosed [4]'],['Model-specific hardware / count',unknown,'Not publicly disclosed [4]'],['Accelerator-hours / duration',unknown,'Not publicly disclosed [4]'],['Energy / emissions',unknown,'Not publicly disclosed [4]'],['Single-model training cost',unknown,'No cost claimed here [4]']],extra:'Anthropic’s later company-wide infrastructure announcement names Google TPUs, AWS Trainium, and NVIDIA GPUs. It does not establish which chips, hours, or dollars belong to Claude 3 Opus. Corporate capacity commitments are excluded from this comparison.',sources:[4,9,11]}
};
function card(key){const m=models[key];return `<article class="model-card" data-case="${key}"><div><p class="small-label">${m.developer}</p><h3>${m.title}</h3><p class="model-summary">${m.summary}</p><p class="source-note">Source: ${m.sources.map(n=>`<a href="#ref${n}">[${n}]</a>`).join(' ')}</p></div><div class="model-facts">${m.facts.map(([l,v,s])=>`<div class="fact"><span>${l}</span><strong>${v}</strong><span class="status">${s}</span></div>`).join('')}</div><p class="model-extra">${m.extra}</p></article>`}
$('#model-detail').innerHTML=Object.keys(models).map(card).join('');
function selectModel(key){$$('[data-case]').forEach(p=>p.hidden=p.dataset.case!==key);$$('[data-model]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.model===key)));}
$$('[data-model]').forEach(b=>b.addEventListener('click',()=>selectModel(b.dataset.model)));selectModel('llama');
const chartData={cost:{title:'Estimated training compute rental expense · millions of USD',values:[170,79,192,null],max:200,labels:['≈ $170M','≈ $79M','≈ $192M',unknown],axis:['$0','$50M','$100M','$150M','$200M'],note:'Independent estimates, not company-reported spending. Linear scale from zero. Epoch AI estimates via Stanford AI Index 2025, Fig. 1.3.24, printed p. 43; inflation-adjusted USD and cloud compute rental basis. Excludes an audited account of total R&D and ongoing serving. [5]'},hours:{title:'Official cumulative training GPU time · millions of H100 GPU-hours',values:[30.84,null,null,null],max:40,labels:['30.84M',unknown,unknown,unknown],axis:['0','10M','20M','30M','40M'],note:'Llama 3.1 405B only; not the 39.3M GPU-hours of the full family. Missing data is not zero. Different accelerator types would require separate performance assumptions before treating their hours as equivalent. [1–4]'},tokens:{title:'Official pretraining corpus scale · trillions of tokens',values:[15,null,null,null],max:20,labels:['≈ 15T',unknown,unknown,unknown],axis:['0','5T','10T','15T','20T'],note:'Meta’s model card describes approximately 15 trillion pretraining tokens (15T+ in its table). Post-training examples are a separate scope. Tokenizers differ, so equal token counts would not necessarily mean equal information. [1–4]'},emissions:{title:'Official location-based training emissions · metric tons CO₂e',values:[8930,null,null,null],max:10000,labels:['8,930 t',unknown,unknown,unknown],axis:['0','2,500','5,000','7,500','10,000'],note:'Developer-reported estimate for Llama 3.1 405B, not family total. Location-based accounting is displayed consistently; Meta’s separate market-based value is not substituted. No comparable model-specific value is claimed for the other releases. [1–4]'}};
function chart(){const d=chartData[$('#metric').value],names=['Llama 3.1 405B','GPT-4','Gemini 1.0 Ultra','Claude 3 Opus'];$('#chart').innerHTML=`<p class="chart-title">${d.title}</p>`+names.map((n,i)=>`<div class="bar-row ${d.values[i]===null?'missing':''}"><span>${n}</span><div class="bar-track" aria-hidden="true">${d.values[i]===null?'':`<div class="bar" style="width:${d.values[i]/d.max*100}%"></div>`}</div><strong>${d.labels[i]}</strong></div>`).join('')+`<div class="axis" aria-hidden="true">${d.axis.map(v=>`<span>${v}</span>`).join('')}</div>`;$('#chart-note').innerHTML=d.note.replace(/\[5\]/g,'<a href="#ref5">[5]</a>').replace(/\[1–4\]/g,'<a href="#ref1">[1]</a> <a href="#ref2">[2]</a> <a href="#ref3">[3]</a> <a href="#ref4">[4]</a>');}
$('#metric').addEventListener('change',chart);chart();
const format=new Intl.NumberFormat('en-US',{maximumFractionDigits:0});
function calculate(){const ids=['gpus','days','rate','power','pue','electric'];if(ids.some(id=>!$('#'+id).validity.valid)){ $('#lab-error').textContent='Enter values within the labeled field limits to calculate.'; ['rental','hours','energy','bill'].forEach(id=>$('#'+id).textContent='—');return;}$('#lab-error').textContent='';const [n,d,r,w,p,e]=ids.map(id=>Number($('#'+id).value));const h=n*d*24,k=h*w/1000*p;$('#rental').textContent='$'+format.format(h*r);$('#hours').textContent=format.format(h);$('#energy').textContent=format.format(k);$('#bill').textContent='$'+format.format(k*e);}
$('#estimator').addEventListener('input',calculate);$('#estimator').addEventListener('submit',e=>e.preventDefault());$('#estimator').addEventListener('reset',()=>setTimeout(calculate,0));calculate();
let openDetails=[];window.addEventListener('beforeprint',()=>{openDetails=$$('details').map(d=>d.open);$$('details').forEach(d=>d.open=true)});window.addEventListener('afterprint',()=>{$$('details').forEach((d,i)=>d.open=openDetails[i])});$('#print').addEventListener('click',()=>window.print());
